<?php
require_once 'db.php'; require_role('customer');
$id=(int)$_SESSION['user_id'];
$stmt=$conn->prepare('SELECT o.id,o.quantity,o.total,o.status,o.created_at,u.name AS vendor_name,m.name AS meal_name FROM orders o JOIN users u ON u.id=o.vendor_id JOIN menu_items m ON m.id=o.menu_id WHERE o.customer_id=? ORDER BY o.created_at DESC');
$stmt->bind_param('i',$id); $stmt->execute(); $orders=$stmt->get_result(); $flash=get_flash();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My orders | Mama Ntilie</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="customer_dashboard.php">🍲 Mama Ntilie</a><a href="logout.php">Sign out</a></header><main class="page-wrap"><a class="back-link" href="customer_dashboard.php">← Dashboard</a><span class="eyebrow">ORDER HISTORY</span><h1>My orders</h1><?php if($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<?php if($orders->num_rows): ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Meal</th><th>Vendor</th><th>Qty</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php while($o=$orders->fetch_assoc()): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= e($o['meal_name']) ?></td><td><?= e($o['vendor_name']) ?></td><td><?= (int)$o['quantity'] ?></td><td><?= money($o['total']) ?></td><td><span class="status <?= e($o['status']) ?>"><?= e(ucfirst($o['status'])) ?></span></td><td><?= e($o['created_at']) ?></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="empty-state">You have not placed any orders yet. <a href="vendors.php">Explore vendors</a>.</div><?php endif; ?></main></body></html>
